const PAGES = {"/privy.html":"<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>司憲院制司受憲秘閣院職官表</title>\n<style>\n:root{\n    --privy-purple:#4b0082;\n    --privy-gold:#d4af37;\n    --privy-border:#a2a9b1;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n    background:#f5f5f5;\n    color:#202122;\n    font-family:\"Noto Serif TC\",\"PingFang TC\",\"Microsoft JhengHei\",serif;\n}\n#privy-app{\n    max-width:1000px;\n    margin:20px auto;\n    font-family:inherit;\n    color:#202122;\n    background:#fff;\n    border:1px solid var(--privy-border);\n    padding:25px;\n    box-shadow:0 4px 12px rgba(0,0,0,.15);\n    line-height:1.6;\n    position:relative;\n}\n#privy-edit-trigger{\n    position:absolute;\n    top:25px;\n    right:25px;\n    cursor:pointer;\n    font-size:18px;\n    color:#eee;\n    transition:color .3s;\n    z-index:999;\n}\n#privy-edit-trigger:hover{color:var(--privy-purple)}\n#privy-header-area{\n    border-bottom:3px solid var(--privy-purple);\n    margin-bottom:20px;\n    padding-bottom:10px;\n    padding-right:35px;\n}\n#privy-header-area h2{\n    margin:0;\n    color:#000;\n    font-size:30px;\n    font-weight:bold;\n    letter-spacing:2px;\n}\n#privy-header-area .subtitle{\n    font-size:14px;\n    color:#54595d;\n    font-style:italic;\n    margin-top:5px;\n}\n\n/* 與內閣共用同一套表格結構 */\n#privy-app .wm-wiki-table{\n    width:100%;\n    border-collapse:collapse;\n    margin-bottom:30px;\n    border:1px solid var(--privy-border);\n    table-layout:fixed;\n}\n#privy-app .wm-wiki-table th{\n    background:#f8f9fa;\n    border:1px solid var(--privy-border);\n    padding:12px 8px;\n    text-align:center;\n    font-weight:bold;\n    color:#000;\n}\n#privy-app .wm-wiki-table td{\n    border:1px solid var(--privy-border);\n    padding:10px 8px;\n    vertical-align:middle;\n}\n\n/* 司憲院紫色部門橫幅 */\n#privy-app .wm-dept-banner,\n#privy-app .wm-privy-banner{\n    background:var(--privy-purple)!important;\n    color:#fff!important;\n    font-size:16px!important;\n    font-weight:bold;\n    text-align:left!important;\n    padding-left:15px!important;\n    letter-spacing:1px;\n}\n\n/* 官員名稱 */\n#privy-app .wm-incumbent,\n#privy-app .name-field{\n    font-weight:900!important;\n    color:#000!important;\n    font-size:16px!important;\n    text-align:left!important;\n    padding-left:15px!important;\n    min-height:1.2em;\n}\n#privy-app .name-field.empty-vacancy:after{\n    content:\"懸缺\";\n    color:#bdc3c7!important;\n    font-style:italic!important;\n    font-weight:normal!important;\n}\n\n/* 肖像 */\n#privy-app .wm-portrait-box{\n    width:80px;\n    height:100px;\n    background:#faf9f6;\n    border:1px solid var(--privy-gold);\n    margin:0 auto;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    overflow:hidden;\n    border-radius:4px;\n    position:relative;\n}\n#privy-app .wm-portrait-box.editable{cursor:pointer}\n#privy-app .wm-portrait-img{\n    width:100%;\n    height:100%;\n    object-fit:cover;\n}\n#privy-app .wm-portrait-placeholder{\n    font-size:11px;\n    color:#888;\n    text-align:center;\n}\n\n/* 職等標籤：保留司憲院紫金色 */\n#privy-app .wm-rank-tag,\n#privy-app .wm-p-rank{\n    display:inline-block;\n    padding:2px 10px;\n    background:#fcf3cf;\n    color:#9a7d0a;\n    border-radius:4px;\n    font-size:12px;\n    font-weight:bold;\n    border:1px solid var(--privy-gold);\n}\n#privy-app .wm-rank-high,\n#privy-app .wm-p-rank-high{\n    background:var(--privy-purple)!important;\n    color:#f1c40f!important;\n    border:1px solid var(--privy-gold)!important;\n}\n#privy-app .wm-rank-subchief{\n    background:#829cc9!important;\n    color:#fff!important;\n    border:1px solid #7189b1;\n}\n#privy-app .wm-rank-adjunct{\n    background:#f1f5f9;\n    color:#64748b;\n    border:1px solid #e2e8f0;\n}\n\n/* 編輯狀態 */\n#privy-app.is-editing [contenteditable=\"true\"]{\n    outline:2px dashed var(--privy-purple)!important;\n    background:#fff8dc!important;\n    cursor:text;\n}\n#privy-app.is-editing .wm-portrait-box{\n    cursor:pointer;\n}\n\n/* 頁尾與同步燈號 */\n#privy-app .wm-sync-footer{\n    font-size:12px;\n    color:#72777d;\n    font-style:italic;\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:12px;\n    border-left:3px solid var(--privy-gold);\n    padding:2px 0 2px 12px;\n    margin-top:15px;\n    line-height:1.5;\n}\n#privy-app #privy-sync-status{\n    display:inline-flex;\n    align-items:center;\n    gap:7px;\n    font-style:normal;\n    font-weight:bold;\n    white-space:nowrap;\n}\n#privy-app #privy-sync-status:before{\n    content:\"\";\n    width:9px;\n    height:9px;\n    border-radius:50%;\n    background:currentColor;\n}\n#privy-app #privy-sync-status.online{color:#27ae60!important}\n#privy-app #privy-sync-status.online:before{\n    animation:privy-green-breathe 1.8s ease-in-out infinite;\n    box-shadow:0 0 5px currentColor;\n}\n#privy-app #privy-sync-status.loading{color:#d4af37!important}\n#privy-app #privy-sync-status.error{color:#e74c3c!important}\n#privy-app #privy-sync-status.local{color:#7f8c8d!important}\n@keyframes privy-green-breathe{\n    0%,100%{opacity:.55;box-shadow:0 0 4px currentColor,0 0 8px rgba(39,174,96,.25)}\n    50%{opacity:1;box-shadow:0 0 8px currentColor,0 0 18px rgba(39,174,96,.6)}\n}\n\n\n#privy-app .privy-edit-tools{\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:12px;\n    padding:10px 12px;\n    margin:-8px 0 16px;\n    border:1px solid #d4af37;\n    background:#fbf8ff;\n    color:#4b0082;\n    font-size:13px;\n}\n#privy-app .privy-edit-tools[hidden]{display:none!important}\n#privy-app .privy-edit-tools button{\n    border:1px solid #4b0082;\n    border-radius:4px;\n    padding:6px 12px;\n    margin-left:6px;\n    background:#4b0082;\n    color:#fff;\n    cursor:pointer;\n    font:inherit;\n}\n#privy-app .privy-edit-tools button:last-child{\n    background:#fff;\n    color:#4b0082;\n}\n#privy-app .privy-edit-tools button:disabled{\n    opacity:.55;\n    cursor:wait;\n}\n.privy-auth-modal{\n    position:fixed;\n    inset:0;\n    z-index:100000;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    padding:18px;\n    background:rgba(0,0,0,.48);\n}\n.privy-auth-modal[hidden]{display:none!important}\n.privy-auth-card{\n    width:min(440px,100%);\n    padding:22px;\n    border:1px solid #a2a9b1;\n    border-top:4px solid #4b0082;\n    border-radius:6px;\n    background:#fff;\n    box-shadow:0 12px 40px rgba(0,0,0,.25);\n    font-family:\"Noto Serif TC\",\"PingFang TC\",\"Microsoft JhengHei\",serif;\n}\n.privy-auth-title{\n    margin-bottom:16px;\n    color:#4b0082;\n    font-size:19px;\n    font-weight:bold;\n}\n.privy-auth-label{\n    display:block;\n    margin:12px 0 5px;\n    font-size:13px;\n    font-weight:bold;\n}\n.privy-auth-input{\n    display:block;\n    width:100%;\n    padding:10px;\n    border:1px solid #a2a9b1;\n    border-radius:4px;\n    font:inherit;\n}\n.privy-auth-help{\n    margin-top:10px;\n    color:#666;\n    font-size:12px;\n    line-height:1.55;\n}\n.privy-auth-error{\n    min-height:20px;\n    margin-top:8px;\n    color:#c0392b;\n    font-size:12px;\n}\n.privy-auth-actions{\n    display:flex;\n    justify-content:flex-end;\n    gap:8px;\n    margin-top:12px;\n}\n.privy-auth-actions button{\n    border:1px solid #4b0082;\n    border-radius:4px;\n    padding:8px 13px;\n    background:#fff;\n    color:#4b0082;\n    cursor:pointer;\n    font:inherit;\n}\n.privy-auth-actions button:last-child{\n    background:#4b0082;\n    color:#fff;\n}\n.privy-auth-actions button:disabled{opacity:.55;cursor:wait}\n\n@media(max-width:700px){\n    #privy-app{\n        margin:0;\n        padding:15px;\n        box-shadow:none;\n    }\n    #privy-header-area h2{font-size:23px}\n    #privy-app .wm-wiki-table{\n        font-size:14px;\n        min-width:760px;\n    }\n    #privy-app .table-scroll{\n        overflow-x:auto;\n        -webkit-overflow-scrolling:touch;\n    }\n    #privy-app .wm-portrait-box{\n        width:64px;\n        height:80px;\n    }\n    #privy-app .wm-sync-footer{\n        align-items:flex-start;\n        flex-direction:column;\n    }\n}\n</style>\n</head>\n<body>\n<main class=\"wm-wiki-wrapper\" id=\"privy-app\">\n    <div id=\"privy-edit-trigger\" title=\"管理員編輯\">⚙️</div>\n\n    <div id=\"privy-header-area\">\n        <h2 class=\"editable-field\">司憲院制司受憲秘閣院職官表</h2>\n        <div class=\"subtitle editable-field\">Privy Council — List of Imperial Secretarial Officials</div>\n    </div>\n\n    <div class=\"privy-edit-tools\" id=\"privy-edit-tools\" hidden>\n        <span>編輯模式：修改完成後儲存修改</span>\n        <div>\n            <button type=\"button\" id=\"privy-save-button\">儲存修改</button>\n            <button type=\"button\" id=\"privy-cancel-button\">取消修改</button>\n        </div>\n    </div>\n\n    <div class=\"table-scroll\">\n        <table class=\"wm-wiki-table\">\n            <thead>\n                <tr>\n                    <th style=\"width:100px;\">肖像</th>\n                    <th style=\"width:200px;\">職銜 (Official Title)</th>\n                    <th style=\"width:100px;\">職等 / 定員</th>\n                    <th style=\"width:160px;\">官員名稱</th>\n                    <th>職掌備註 (Notes)</th>\n                </tr>\n            </thead>\n            <tbody id=\"privy-table-body\"></tbody>\n        </table>\n    </div>\n\n    <div class=\"wm-sync-footer\">\n        <span class=\"editable-field\" id=\"privy-footer-text\">註：司憲院為皇家直屬秘書機關，直接向皇帝負責，獨立於內閣行政體系。</span>\n        <span id=\"privy-sync-status\" class=\"loading\">讀取中</span>\n    </div>\n</main>\n\n<script>\n(function(){\n    const app=document.getElementById('privy-app');\n    if(!app || app.dataset.initialized==='true') return;\n    app.dataset.initialized='true';\n\n    const tb=document.getElementById('privy-table-body');\n    const status=document.getElementById('privy-sync-status');\n    const header=document.getElementById('privy-header-area');\n    const footer=document.getElementById('privy-footer-text');\n\n    const PRIVY_API='/api/privy';\n    const PRIVY_LEGACY_API='https://wme-households-api.onrender.com/api/privy';\n    let privyLegacyMode=false;\n    async function fetchPrivyApi(options){\n        if(privyLegacyMode){\n            const legacyOptions={...options,headers:{...(options.headers||{})}};\n            if(legacyOptions.headers['X-WME-Edit-Password']){\n                legacyOptions.headers['X-Privy-Password']=legacyOptions.headers['X-WME-Edit-Password'];\n                delete legacyOptions.headers['X-WME-Edit-Password'];\n            }\n            return fetch(PRIVY_LEGACY_API,legacyOptions);\n        }\n        const response=await fetch(PRIVY_API,options);\n        const contentType=response.headers.get('content-type')||'';\n        if(response.status===404 && !contentType.includes('application/json')){\n            privyLegacyMode=true;\n            const legacyOptions={...options,headers:{...(options.headers||{})}};\n            if(legacyOptions.headers['X-WME-Edit-Password']){\n                legacyOptions.headers['X-Privy-Password']=legacyOptions.headers['X-WME-Edit-Password'];\n                delete legacyOptions.headers['X-WME-Edit-Password'];\n            }\n            return fetch(PRIVY_LEGACY_API,legacyOptions);\n        }\n        return response;\n    }\n    const PRIVY_RAW='https://raw.githubusercontent.com/annynn1990/wme-list/main/data.json';\n\n    let privyPassword='';\n    let editing=false;\n    let backup=null;\n\n    const INITIAL_HTML=\"<tr><th colspan=\\\"5\\\" class=\\\"wm-privy-banner\\\">院領導核心 (The High Council)</th></tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/00/02_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\"><b>大司憲</b></td>\\n<td><span class=\\\"wm-p-rank wm-p-rank-high\\\">Rank 1</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">李迎希</td>\\n<td class=\\\"col-txt\\\">首席秘書官；兼任選舉委員會主席</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/01/90_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\"><b>二司憲</b></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 2</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">白敖</td>\\n<td class=\\\"col-txt\\\">副秘書長</td>\\n</tr>\\n<tr><th colspan=\\\"5\\\" class=\\\"wm-privy-banner\\\">下設處室與司局 (Departments & Bureaus)</th></tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"></div></td>\\n<td class=\\\"col-txt\\\">制司處處長<br><small>（司制）</small></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 4</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\"></td>\\n<td class=\\\"col-txt\\\">掌管詔書制作</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/03/33_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\">受憲處處長<br><small>（司典）</small></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 4</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">夏侯昜</td>\\n<td class=\\\"col-txt\\\">掌管典章憲制</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/00/89_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\">檔案處處長<br><small>（司吏）</small></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 4</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">小羽</td>\\n<td class=\\\"col-txt\\\">掌管皇家檔案與吏事</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/00/28_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\">司政處處長<br><small>（司政）</small></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 4</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">仲尼</td>\\n<td class=\\\"col-txt\\\">掌管行政文書</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"><img src=\\\"https://www.wongmingempire.com/bbswm/uc_server/data/avatar/000/00/00/11_avatar_middle.jpg\\\" class=\\\"wm-portrait-img\\\"></div></td>\\n<td class=\\\"col-txt\\\">律令司<br><small>（司律）</small></td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 4</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\">路德維希</td>\\n<td class=\\\"col-txt\\\">掌管皇室律令</td>\\n</tr>\\n<tr>\\n<td><div class=\\\"wm-portrait-box\\\"></div></td>\\n<td class=\\\"col-txt\\\">宗正司</td>\\n<td><span class=\\\"wm-p-rank\\\">Rank 5</span><br><small>定員 1</small></td>\\n<td class=\\\"col-txt name-field\\\"></td>\\n<td class=\\\"col-txt\\\">掌管宗室事務</td>\\n</tr>\";\n\n    function setStatus(message,state){\n        status.textContent=message;\n        status.className=state;\n    }\n\n    function cleanEmptyNames(){\n        tb.querySelectorAll('.name-field').forEach(function(el){\n            if(el.textContent.trim()===''){\n                el.innerHTML='';\n                el.classList.add('empty-vacancy');\n            }else{\n                el.classList.remove('empty-vacancy');\n            }\n        });\n    }\n\n    function safeHTML(element){\n        const copy=element.cloneNode(true);\n        copy.removeAttribute('contenteditable');\n        copy.removeAttribute('data-edit-enabled');\n        copy.removeAttribute('spellcheck');\n        copy.querySelectorAll('[contenteditable],[data-edit-enabled],[spellcheck]').forEach(function(node){\n            node.removeAttribute('contenteditable');\n            node.removeAttribute('data-edit-enabled');\n            node.removeAttribute('spellcheck');\n        });\n        copy.querySelectorAll('.wm-portrait-box.editable').forEach(function(node){\n            node.classList.remove('editable');\n        });\n        return copy.innerHTML;\n    }\n\n    function getSnapshot(){\n        return {\n            header:safeHTML(header),\n            table:safeHTML(tb),\n            footer:safeHTML(footer)\n        };\n    }\n\n    function lockDownEditing(){\n        editing=false;\n        app.classList.remove('is-editing');\n        app.querySelectorAll('[contenteditable],[data-edit-enabled],[spellcheck]').forEach(function(node){\n            node.removeAttribute('contenteditable');\n            node.removeAttribute('data-edit-enabled');\n            node.removeAttribute('spellcheck');\n        });\n        app.querySelectorAll('.wm-portrait-box.editable').forEach(function(node){\n            node.classList.remove('editable');\n        });\n        const tools=document.getElementById('privy-edit-tools');\n        if(tools) tools.hidden=true;\n    }\n\n    function markDirty(){\n        if(editing) setStatus('尚未儲存','loading');\n    }\n\n    function makeEditable(el){\n        if(el.dataset.editEnabled==='true') return;\n        el.dataset.editEnabled='true';\n        el.contentEditable='true';\n        el.spellcheck=false;\n        el.addEventListener('input',function(){\n            if(el.classList.contains('name-field')){\n                if(el.textContent.trim()===''){\n                    el.innerHTML='';\n                    el.classList.add('empty-vacancy');\n                }else{\n                    el.classList.remove('empty-vacancy');\n                }\n            }\n            markDirty();\n        });\n    }\n\n    function enableEditing(){\n        if(editing) return;\n        backup={\n            header:header.innerHTML,\n            table:tb.innerHTML,\n            footer:footer.innerHTML\n        };\n        editing=true;\n        app.classList.add('is-editing');\n\n        app.querySelectorAll('.editable-field').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table th').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table td.col-txt').forEach(makeEditable);\n        app.querySelectorAll('.wm-p-rank,.wm-rank-tag').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table td small').forEach(makeEditable);\n        tb.querySelectorAll('.wm-portrait-box').forEach(function(box){\n            box.classList.add('editable');\n        });\n\n        const tools=document.getElementById('privy-edit-tools');\n        if(tools) tools.hidden=false;\n        setStatus('在線中','online');\n    }\n\n    function setBackup(){\n        if(!backup) return;\n        header.innerHTML=backup.header;\n        tb.innerHTML=backup.table;\n        footer.innerHTML=backup.footer;\n        cleanEmptyNames();\n    }\n\n    function closeEditing(){\n        lockDownEditing();\n        privyPassword='';\n        backup=null;\n    }\n\n\n    function createAuthModal(){\n        let modal=document.getElementById('privy-auth-modal');\n        if(modal) return modal;\n\n        modal=document.createElement('div');\n        modal.id='privy-auth-modal';\n        modal.className='privy-auth-modal';\n        modal.hidden=true;\n        modal.innerHTML=\n            '<div class=\"privy-auth-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"privy-auth-title\">'+\n                '<div class=\"privy-auth-title\" id=\"privy-auth-title\">司憲院管理員驗證</div>'+\n                '<label class=\"privy-auth-label\" for=\"privy-admin-password\">管理密碼</label>'+\n                '<input class=\"privy-auth-input\" id=\"privy-admin-password\" type=\"password\" autocomplete=\"off\" placeholder=\"輸入管理密碼\">'+\n                '<div class=\"privy-auth-help\">輸入管理密碼即可編輯，修改後直接儲存至雲端。</div>'+\n                '<div class=\"privy-auth-error\" id=\"privy-auth-error\"></div>'+\n                '<div class=\"privy-auth-actions\">'+\n                    '<button type=\"button\" id=\"privy-auth-cancel\">取消</button>'+\n                    '<button type=\"button\" id=\"privy-auth-submit\">驗證並編輯</button>'+\n                '</div>'+\n            '</div>';\n\n        document.body.appendChild(modal);\n\n        const passwordInput=modal.querySelector('#privy-admin-password');\n        const error=modal.querySelector('#privy-auth-error');\n\n        function dismiss(){\n            modal.hidden=true;\n            passwordInput.value='';\n            error.textContent='';\n        }\n\n        modal.querySelector('#privy-auth-cancel').addEventListener('click',dismiss);\n\n        modal.querySelector('#privy-auth-submit').addEventListener('click',async function(){\n            const password=passwordInput.value;\n            if(!password){\n                error.textContent='請輸入管理密碼。';\n                return;\n            }\n\n            const button=modal.querySelector('#privy-auth-submit');\n            button.disabled=true;\n            error.textContent='正在驗證……';\n\n            try{\n                await verifyPrivyPassword(password);\n                privyPassword=password;\n                dismiss();\n                enableEditing();\n            }catch(e){\n                error.textContent=e.message||'管理員驗證失敗。';\n            }finally{\n                button.disabled=false;\n            }\n        });\n\n        modal.addEventListener('keydown',function(e){\n            if(e.key==='Escape') dismiss();\n            if(e.key==='Enter' && e.target.tagName==='INPUT'){\n                modal.querySelector('#privy-auth-submit').click();\n            }\n        });\n\n        return modal;\n    }\n\n    async function verifyPrivyPassword(password){\n        const response=await fetchPrivyApi({\n            method:'POST',\n            headers:{'Content-Type':'application/json'},\n            body:JSON.stringify({action:'verify',password:password}),\n            cache:'no-store'\n        });\n        const result=await response.json().catch(function(){return {};});\n        if(response.status===403) throw new Error('管理密碼錯誤。');\n        if(!response.ok) throw new Error(result.error||('驗證服務暫時無法使用（HTTP '+response.status+'）。'));\n        return true;\n    }\n\n    async function saveToCloud(){\n        if(!editing || !privyPassword) return;\n\n        const saveButton=document.getElementById('privy-save-button');\n        if(saveButton) saveButton.disabled=true;\n        setStatus('正在儲存','loading');\n\n        try{\n            const response=await fetchPrivyApi({\n                method:'PUT',\n                headers:{\n                    'Content-Type':'application/json',\n                    'X-WME-Edit-Password':privyPassword\n                },\n                body:JSON.stringify({savedData:getSnapshot()}),\n                cache:'no-store'\n            });\n            const result=await response.json().catch(function(){return {};});\n            if(!response.ok) throw new Error(result.error||('雲端儲存失敗（HTTP '+response.status+'）。'));\n\n            closeEditing();\n            setStatus('在線中','online');\n        }catch(e){\n            setStatus('離線中','error');\n            alert(e.message||'雲端儲存失敗，修改尚未提交。');\n        }finally{\n            if(saveButton) saveButton.disabled=false;\n        }\n    }\n\n    function bindToolbar(){\n        const saveButton=document.getElementById('privy-save-button');\n        const cancelButton=document.getElementById('privy-cancel-button');\n        if(saveButton) saveButton.addEventListener('click',saveToCloud);\n        if(cancelButton) cancelButton.addEventListener('click',cancelEditing);\n    }\n\n    function cancelEditing(){\n        if(!editing) return;\n        if(!confirm('放棄本次尚未提交的修改？')) return;\n        setBackup();\n        closeEditing();\n        setStatus('在線中','online');\n    }\n\n\n    tb.addEventListener('click',function(e){\n        if(!editing) return;\n        const box=e.target.closest('.wm-portrait-box');\n        if(!box) return;\n\n        const url=prompt('輸入新肖像網址：');\n        if(!url) return;\n\n        try{\n            const parsed=new URL(url.trim());\n            if(parsed.protocol!=='https:' && parsed.protocol!=='http:'){\n                alert('請輸入有效的圖片網址。');\n                return;\n            }\n            const img=document.createElement('img');\n            img.src=parsed.href;\n            img.className='wm-portrait-img';\n            img.alt='官員肖像';\n            box.replaceChildren(img);\n            markDirty();\n        }catch(e){\n            alert('圖片網址格式不正確。');\n        }\n    });\n\n    async function loadData(){\n        setStatus('讀取中','loading');\n        let timeout=null;\n        try{\n            const controller=new AbortController();\n            timeout=setTimeout(function(){controller.abort();},12000);\n            let response=await fetch(PRIVY_API,{\n                cache:'no-store',\n                signal:controller.signal\n            });\n            const apiContentType=response.headers.get('content-type')||'';\n            if(response.status===404 && !apiContentType.includes('application/json')){\n                response=await fetch('./data.json',{\n                    cache:'no-cache',\n                    signal:controller.signal\n                });\n            }\n            if(!response.ok) throw new Error('司憲院資料讀取失敗（HTTP '+response.status+'）。');\n            const data=await response.json();\n            if(data.savedData){\n                if(typeof data.savedData.header==='string') header.innerHTML=data.savedData.header;\n                if(typeof data.savedData.table==='string') tb.innerHTML=data.savedData.table;\n                if(typeof data.savedData.footer==='string') footer.innerHTML=data.savedData.footer;\n            }else if(typeof data.savedHTML==='string'){\n                tb.innerHTML=data.savedHTML;\n            }else{\n                throw new Error('data.json 缺少 savedHTML。');\n            }\n            lockDownEditing();\n            cleanEmptyNames();\n            status.title='';\n            setStatus('在線中','online');\n        }catch(e){\n            console.error('司憲院資料讀取失敗：',e);\n            tb.innerHTML=INITIAL_HTML;\n            lockDownEditing();\n            cleanEmptyNames();\n            status.title=e && e.message ? e.message : '未知讀取錯誤';\n            setStatus('離線中','error');\n        }finally{\n            if(timeout!==null) clearTimeout(timeout);\n            scheduleEmbedHeight();\n        }\n    }\n\n    const editTrigger=document.getElementById('privy-edit-trigger');\n    editTrigger.addEventListener('click',function(){\n        if(editing) return;\n        const modal=createAuthModal();\n        modal.hidden=false;\n        const passwordInput=modal.querySelector('#privy-admin-password');\n        setTimeout(function(){passwordInput.focus();},0);\n    });\n\n    bindToolbar();\n    loadData().then(scheduleEmbedHeight);\n\n    // iframe 嵌入支援：只回報內容本身高度，不把 iframe 視窗高度算進去。\n    function notifyEmbedHeight(){\n        if(window.parent===window) return;\n        const rect=app.getBoundingClientRect();\n        const style=window.getComputedStyle(app);\n        const marginBottom=parseFloat(style.marginBottom)||0;\n        const height=Math.ceil(rect.bottom+window.scrollY+marginBottom);\n        window.parent.postMessage({\n            type:'wme-privy-embed-height',\n            height:Math.max(height,1)\n        },'*');\n    }\n\n    let embedHeightFrame=0;\n    function scheduleEmbedHeight(){\n        if(window.parent===window) return;\n        cancelAnimationFrame(embedHeightFrame);\n        embedHeightFrame=requestAnimationFrame(function(){\n            requestAnimationFrame(notifyEmbedHeight);\n        });\n    }\n\n    if(window.parent!==window){\n        window.addEventListener('load',scheduleEmbedHeight);\n        window.addEventListener('resize',scheduleEmbedHeight);\n\n        if('ResizeObserver' in window){\n            const embedResizeObserver=new ResizeObserver(scheduleEmbedHeight);\n            embedResizeObserver.observe(document.documentElement);\n            embedResizeObserver.observe(app);\n        }\n\n        const embedMutationObserver=new MutationObserver(scheduleEmbedHeight);\n        embedMutationObserver.observe(app,{\n            childList:true,\n            subtree:true,\n            characterData:true,\n            attributes:true\n        });\n\n        if(document.fonts && document.fonts.ready){\n            document.fonts.ready.then(scheduleEmbedHeight);\n        }\n        scheduleEmbedHeight();\n    }\n\n\n})();\n</script>\n</body>\n</html>\n","/cabinet.html":"<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>第三十三屆內閣政府職官表</title>\n<style>\n:root{\n    --cabinet-purple:#1a365d;\n    --cabinet-gold:#d4af37;\n    --cabinet-border:#a2a9b1;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n    background:#f5f5f5;\n    color:#202122;\n    font-family:\"Noto Serif TC\",\"PingFang TC\",\"Microsoft JhengHei\",serif;\n}\n#cabinet-app{\n    max-width:1000px;\n    margin:20px auto;\n    font-family:inherit;\n    color:#202122;\n    background:#fff;\n    border:1px solid var(--cabinet-border);\n    padding:25px;\n    box-shadow:0 4px 12px rgba(0,0,0,.15);\n    line-height:1.6;\n    position:relative;\n}\n#cabinet-edit-trigger{\n    position:absolute;\n    top:25px;\n    right:25px;\n    cursor:pointer;\n    font-size:18px;\n    color:#eee;\n    transition:color .3s;\n    z-index:999;\n}\n#cabinet-edit-trigger:hover{color:var(--cabinet-purple)}\n#cabinet-header-area{\n    border-bottom:3px solid var(--cabinet-purple);\n    margin-bottom:20px;\n    padding-bottom:10px;\n    padding-right:35px;\n}\n#cabinet-header-area h2{\n    margin:0;\n    color:#000;\n    font-size:30px;\n    font-weight:bold;\n    letter-spacing:2px;\n}\n#cabinet-header-area .subtitle{\n    font-size:14px;\n    color:#54595d;\n    font-style:italic;\n    margin-top:5px;\n}\n\n/* 與內閣共用同一套表格結構 */\n#cabinet-app .wm-wiki-table{\n    width:100%;\n    border-collapse:collapse;\n    margin-bottom:30px;\n    border:1px solid var(--cabinet-border);\n    table-layout:fixed;\n}\n#cabinet-app .wm-wiki-table th{\n    background:#f8f9fa;\n    border:1px solid var(--cabinet-border);\n    padding:12px 8px;\n    text-align:center;\n    font-weight:bold;\n    color:#000;\n}\n#cabinet-app .wm-wiki-table td{\n    border:1px solid var(--cabinet-border);\n    padding:10px 8px;\n    vertical-align:middle;\n}\n\n/* 司憲院紫色部門橫幅 */\n#cabinet-app .wm-dept-banner,\n#cabinet-app .wm-cabinet-banner{\n    background:var(--cabinet-purple)!important;\n    color:#fff!important;\n    font-size:16px!important;\n    font-weight:bold;\n    text-align:left!important;\n    padding-left:15px!important;\n    letter-spacing:1px;\n}\n\n/* 官員名稱 */\n#cabinet-app .wm-incumbent,\n#cabinet-app .name-field{\n    font-weight:900!important;\n    color:#000!important;\n    font-size:16px!important;\n    text-align:left!important;\n    padding-left:15px!important;\n    min-height:1.2em;\n}\n#cabinet-app .name-field.empty-vacancy:after{\n    content:\"懸缺\";\n    color:#bdc3c7!important;\n    font-style:italic!important;\n    font-weight:normal!important;\n}\n\n/* 肖像 */\n#cabinet-app .wm-portrait-box{\n    width:80px;\n    height:100px;\n    background:#faf9f6;\n    border:1px solid var(--cabinet-gold);\n    margin:0 auto;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    overflow:hidden;\n    border-radius:4px;\n    position:relative;\n}\n#cabinet-app .wm-portrait-box.editable{cursor:pointer}\n#cabinet-app .wm-portrait-img{\n    width:100%;\n    height:100%;\n    object-fit:cover;\n}\n#cabinet-app .wm-portrait-placeholder{\n    font-size:11px;\n    color:#888;\n    text-align:center;\n}\n\n/* 職等標籤：保留司憲院紫金色 */\n#cabinet-app .wm-rank-tag,\n#cabinet-app .wm-p-rank{\n    display:inline-block;\n    padding:2px 10px;\n    background:#fcf3cf;\n    color:#9a7d0a;\n    border-radius:4px;\n    font-size:12px;\n    font-weight:bold;\n    border:1px solid var(--cabinet-gold);\n}\n#cabinet-app .wm-rank-high,\n#cabinet-app .wm-p-rank-high{\n    background:var(--cabinet-purple)!important;\n    color:#f1c40f!important;\n    border:1px solid var(--cabinet-gold)!important;\n}\n#cabinet-app .wm-rank-subchief{\n    background:#829cc9!important;\n    color:#fff!important;\n    border:1px solid #7189b1;\n}\n#cabinet-app .wm-rank-adjunct{\n    background:#f1f5f9;\n    color:#64748b;\n    border:1px solid #e2e8f0;\n}\n\n/* 編輯狀態 */\n#cabinet-app.is-editing [contenteditable=\"true\"]{\n    outline:2px dashed var(--cabinet-purple)!important;\n    background:#fff8dc!important;\n    cursor:text;\n}\n#cabinet-app.is-editing .wm-portrait-box{\n    cursor:pointer;\n}\n\n/* 頁尾與同步燈號 */\n#cabinet-app .wm-sync-footer{\n    font-size:12px;\n    color:#72777d;\n    font-style:italic;\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:12px;\n    border-left:3px solid var(--cabinet-gold);\n    padding:2px 0 2px 12px;\n    margin-top:15px;\n    line-height:1.5;\n}\n#cabinet-app #cabinet-sync-status{\n    display:inline-flex;\n    align-items:center;\n    gap:7px;\n    font-style:normal;\n    font-weight:bold;\n    white-space:nowrap;\n}\n#cabinet-app #cabinet-sync-status:before{\n    content:\"\";\n    width:9px;\n    height:9px;\n    border-radius:50%;\n    background:currentColor;\n}\n#cabinet-app #cabinet-sync-status.online{color:#27ae60!important}\n#cabinet-app #cabinet-sync-status.online:before{\n    animation:cabinet-green-breathe 1.8s ease-in-out infinite;\n    box-shadow:0 0 5px currentColor;\n}\n#cabinet-app #cabinet-sync-status.loading{color:#d4af37!important}\n#cabinet-app #cabinet-sync-status.error{color:#e74c3c!important}\n#cabinet-app #cabinet-sync-status.local{color:#7f8c8d!important}\n@keyframes cabinet-green-breathe{\n    0%,100%{opacity:.55;box-shadow:0 0 4px currentColor,0 0 8px rgba(39,174,96,.25)}\n    50%{opacity:1;box-shadow:0 0 8px currentColor,0 0 18px rgba(39,174,96,.6)}\n}\n\n\n#cabinet-app .cabinet-edit-tools{\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:12px;\n    padding:10px 12px;\n    margin:-8px 0 16px;\n    border:1px solid #d4af37;\n    background:#fbf8ff;\n    color:#1a365d;\n    font-size:13px;\n}\n#cabinet-app .cabinet-edit-tools[hidden]{display:none!important}\n#cabinet-app .cabinet-edit-tools button{\n    border:1px solid #1a365d;\n    border-radius:4px;\n    padding:6px 12px;\n    margin-left:6px;\n    background:#1a365d;\n    color:#fff;\n    cursor:pointer;\n    font:inherit;\n}\n#cabinet-app .cabinet-edit-tools button:last-child{\n    background:#fff;\n    color:#1a365d;\n}\n#cabinet-app .cabinet-edit-tools button:disabled{\n    opacity:.55;\n    cursor:wait;\n}\n.cabinet-auth-modal{\n    position:fixed;\n    inset:0;\n    z-index:100000;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    padding:18px;\n    background:rgba(0,0,0,.48);\n}\n.cabinet-auth-modal[hidden]{display:none!important}\n.cabinet-auth-card{\n    width:min(440px,100%);\n    padding:22px;\n    border:1px solid #a2a9b1;\n    border-top:4px solid #1a365d;\n    border-radius:6px;\n    background:#fff;\n    box-shadow:0 12px 40px rgba(0,0,0,.25);\n    font-family:\"Noto Serif TC\",\"PingFang TC\",\"Microsoft JhengHei\",serif;\n}\n.cabinet-auth-title{\n    margin-bottom:16px;\n    color:#1a365d;\n    font-size:19px;\n    font-weight:bold;\n}\n.cabinet-auth-label{\n    display:block;\n    margin:12px 0 5px;\n    font-size:13px;\n    font-weight:bold;\n}\n.cabinet-auth-input{\n    display:block;\n    width:100%;\n    padding:10px;\n    border:1px solid #a2a9b1;\n    border-radius:4px;\n    font:inherit;\n}\n.cabinet-auth-help{\n    margin-top:10px;\n    color:#666;\n    font-size:12px;\n    line-height:1.55;\n}\n.cabinet-auth-error{\n    min-height:20px;\n    margin-top:8px;\n    color:#c0392b;\n    font-size:12px;\n}\n.cabinet-auth-actions{\n    display:flex;\n    justify-content:flex-end;\n    gap:8px;\n    margin-top:12px;\n}\n.cabinet-auth-actions button{\n    border:1px solid #1a365d;\n    border-radius:4px;\n    padding:8px 13px;\n    background:#fff;\n    color:#1a365d;\n    cursor:pointer;\n    font:inherit;\n}\n.cabinet-auth-actions button:last-child{\n    background:#1a365d;\n    color:#fff;\n}\n.cabinet-auth-actions button:disabled{opacity:.55;cursor:wait}\n\n@media(max-width:700px){\n    #cabinet-app{\n        margin:0;\n        padding:15px;\n        box-shadow:none;\n    }\n    #cabinet-header-area h2{font-size:23px}\n    #cabinet-app .wm-wiki-table{\n        font-size:14px;\n        min-width:760px;\n    }\n    #cabinet-app .table-scroll{\n        overflow-x:auto;\n        -webkit-overflow-scrolling:touch;\n    }\n    #cabinet-app .wm-portrait-box{\n        width:64px;\n        height:80px;\n    }\n    #cabinet-app .wm-sync-footer{\n        align-items:flex-start;\n        flex-direction:column;\n    }\n}\n\n/* 內閣深藍色樣式：版面與司憲院一致，色系沿用內閣原設計 */\n#cabinet-app .wm-dept-banner{\n    background:#1a365d!important;\n    color:#fff!important;\n    font-size:16px!important;\n    font-weight:bold;\n    text-align:left!important;\n    padding-left:15px!important;\n    letter-spacing:1px;\n}\n#cabinet-app .wm-incumbent,\n#cabinet-app .name-field{\n    font-weight:900!important;\n    color:#000!important;\n    font-size:16px!important;\n    text-align:left!important;\n    padding-left:15px!important;\n    min-height:1.2em;\n}\n#cabinet-app .wm-portrait-box{\n    background:#f0f0f0;\n    border:1px solid #ccc;\n}\n#cabinet-app .wm-p-rank,\n#cabinet-app .wm-rank-tag{\n    background:#e2e8f0!important;\n    color:#1a365d!important;\n    border:1px solid #cbd5e1!important;\n    border-radius:12px;\n}\n#cabinet-app .wm-p-rank-high,\n#cabinet-app .wm-rank-high{\n    background:#fef3c7!important;\n    color:#92400e!important;\n    border:1px solid #fcd34d!important;\n}\n#cabinet-app .wm-rank-subchief{\n    background:#829cc9!important;\n    color:#fff!important;\n    border:1px solid #7189b1!important;\n}\n#cabinet-app .wm-rank-adjunct{\n    background:#f1f5f9!important;\n    color:#64748b!important;\n    border:1px solid #e2e8f0!important;\n}\n#cabinet-app .cabinet-empty{\n    padding:42px 16px!important;\n    text-align:center!important;\n    color:#64748b!important;\n    font-style:italic;\n}\n\n</style>\n</head>\n<body>\n<main class=\"wm-wiki-wrapper\" id=\"cabinet-app\">\n    <div id=\"cabinet-edit-trigger\" title=\"管理員編輯\">⚙️</div>\n\n    <div id=\"cabinet-header-area\">\n        <h2 class=\"editable-field\">第三十三屆內閣政府職官表</h2>\n        <div class=\"subtitle editable-field\">Cabinet Government — List of Officials of the 33rd Cabinet</div>\n    </div>\n\n    <div class=\"cabinet-edit-tools\" id=\"cabinet-edit-tools\" hidden>\n        <span>編輯模式：修改完成後儲存至雲端</span>\n        <div>\n            <button type=\"button\" id=\"cabinet-save-button\">儲存修改</button>\n            <button type=\"button\" id=\"cabinet-cancel-button\">取消修改</button>\n        </div>\n    </div>\n\n    <div class=\"table-scroll\">\n        <table class=\"wm-wiki-table\">\n            <thead>\n                <tr>\n                    <th style=\"width:100px;\">肖像</th>\n                    <th style=\"width:200px;\">職銜 (Official Title)</th>\n                    <th style=\"width:100px;\">職等 / 定員</th>\n                    <th style=\"width:160px;\">官員名稱 (Name)</th>\n                    <th>備註 (Notes)</th>\n                </tr>\n            </thead>\n            <tbody id=\"cabinet-table-body\"></tbody>\n        </table>\n    </div>\n\n    <div class=\"wm-sync-footer\">\n        <span class=\"editable-field\" id=\"cabinet-footer-text\">註：Rank 為職等標註，國策顧問不在此列。</span>\n        <span id=\"cabinet-sync-status\" class=\"loading\">讀取中</span>\n    </div>\n</main>\n\n<script>\n(function(){\n    const app=document.getElementById('cabinet-app');\n    if(!app || app.dataset.initialized==='true') return;\n    app.dataset.initialized='true';\n\n    const tb=document.getElementById('cabinet-table-body');\n    const status=document.getElementById('cabinet-sync-status');\n    const header=document.getElementById('cabinet-header-area');\n    const footer=document.getElementById('cabinet-footer-text');\n\n    const CABINET_API='/api/cabinet';\n    const CABINET_LEGACY_API='https://wme-households-api.onrender.com/api/cabinet';\n    let cabinetLegacyMode=false;\n    async function fetchCabinetApi(options){\n        if(cabinetLegacyMode){\n            const legacyOptions={...options,headers:{...(options.headers||{})}};\n            if(legacyOptions.headers['X-WME-Edit-Password']){\n                legacyOptions.headers['X-Cabinet-Password']=legacyOptions.headers['X-WME-Edit-Password'];\n                delete legacyOptions.headers['X-WME-Edit-Password'];\n            }\n            return fetch(CABINET_LEGACY_API,legacyOptions);\n        }\n        const response=await fetch(CABINET_API,options);\n        const contentType=response.headers.get('content-type')||'';\n        if(response.status===404 && !contentType.includes('application/json')){\n            cabinetLegacyMode=true;\n            const legacyOptions={...options,headers:{...(options.headers||{})}};\n            if(legacyOptions.headers['X-WME-Edit-Password']){\n                legacyOptions.headers['X-Cabinet-Password']=legacyOptions.headers['X-WME-Edit-Password'];\n                delete legacyOptions.headers['X-WME-Edit-Password'];\n            }\n            return fetch(CABINET_LEGACY_API,legacyOptions);\n        }\n        return response;\n    }\n    const CABINET_RAW='https://raw.githubusercontent.com/annynn1990/wme-list/main/cabinet.json';\n\n    let cabinetPassword='';\n    let editing=false;\n    let backup=null;\n\n    const INITIAL_HTML=\"<tr><td colspan=\\\"5\\\" class=\\\"cabinet-empty\\\">第三十三屆內閣政府職官表資料讀取失敗</td></tr>\";\n\n    function setStatus(message,state){\n        status.textContent=message;\n        status.className=state;\n    }\n\n    function cleanEmptyNames(){\n        tb.querySelectorAll('.name-field').forEach(function(el){\n            if(el.textContent.trim()===''){\n                el.innerHTML='';\n                el.classList.add('empty-vacancy');\n            }else{\n                el.classList.remove('empty-vacancy');\n            }\n        });\n    }\n\n    function safeHTML(element){\n        const copy=element.cloneNode(true);\n        copy.removeAttribute('contenteditable');\n        copy.removeAttribute('data-edit-enabled');\n        copy.removeAttribute('spellcheck');\n        copy.querySelectorAll('[contenteditable],[data-edit-enabled],[spellcheck]').forEach(function(node){\n            node.removeAttribute('contenteditable');\n            node.removeAttribute('data-edit-enabled');\n            node.removeAttribute('spellcheck');\n        });\n        copy.querySelectorAll('.wm-portrait-box.editable').forEach(function(node){\n            node.classList.remove('editable');\n        });\n        return copy.innerHTML;\n    }\n\n    function getSnapshot(){\n        return {\n            header:safeHTML(header),\n            table:safeHTML(tb),\n            footer:safeHTML(footer)\n        };\n    }\n\n    function lockDownEditing(){\n        editing=false;\n        app.classList.remove('is-editing');\n        app.querySelectorAll('[contenteditable],[data-edit-enabled],[spellcheck]').forEach(function(node){\n            node.removeAttribute('contenteditable');\n            node.removeAttribute('data-edit-enabled');\n            node.removeAttribute('spellcheck');\n        });\n        app.querySelectorAll('.wm-portrait-box.editable').forEach(function(node){\n            node.classList.remove('editable');\n        });\n        const tools=document.getElementById('cabinet-edit-tools');\n        if(tools) tools.hidden=true;\n    }\n\n    function markDirty(){\n        if(editing) setStatus('尚未儲存','loading');\n    }\n\n    function makeEditable(el){\n        if(el.dataset.editEnabled==='true') return;\n        el.dataset.editEnabled='true';\n        el.contentEditable='true';\n        el.spellcheck=false;\n        el.addEventListener('input',function(){\n            if(el.classList.contains('name-field')){\n                if(el.textContent.trim()===''){\n                    el.innerHTML='';\n                    el.classList.add('empty-vacancy');\n                }else{\n                    el.classList.remove('empty-vacancy');\n                }\n            }\n            markDirty();\n        });\n    }\n\n    function enableEditing(){\n        if(editing) return;\n        backup={\n            header:header.innerHTML,\n            table:tb.innerHTML,\n            footer:footer.innerHTML\n        };\n        editing=true;\n        app.classList.add('is-editing');\n\n        app.querySelectorAll('.editable-field').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table th').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table td.col-txt,.wm-wiki-table td.wm-incumbent,.wm-wiki-table td.editable-field').forEach(makeEditable);\n        app.querySelectorAll('.wm-p-rank,.wm-rank-tag,.wm-rank-high,.wm-rank-subchief,.wm-rank-adjunct').forEach(makeEditable);\n        app.querySelectorAll('.wm-wiki-table td small').forEach(makeEditable);\n        tb.querySelectorAll('.wm-portrait-box,.portrait-cell .wm-portrait-box').forEach(function(box){\n            box.classList.add('editable');\n        });\n\n        const tools=document.getElementById('cabinet-edit-tools');\n        if(tools) tools.hidden=false;\n        setStatus('在線中','online');\n    }\n\n    function setBackup(){\n        if(!backup) return;\n        header.innerHTML=backup.header;\n        tb.innerHTML=backup.table;\n        footer.innerHTML=backup.footer;\n        cleanEmptyNames();\n    }\n\n    function closeEditing(){\n        lockDownEditing();\n        cabinetPassword='';\n        backup=null;\n    }\n\n\n    function createAuthModal(){\n        let modal=document.getElementById('cabinet-auth-modal');\n        if(modal) return modal;\n\n        modal=document.createElement('div');\n        modal.id='cabinet-auth-modal';\n        modal.className='cabinet-auth-modal';\n        modal.hidden=true;\n        modal.innerHTML=\n            '<div class=\"cabinet-auth-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cabinet-auth-title\">'+\n                '<div class=\"cabinet-auth-title\" id=\"cabinet-auth-title\">內閣管理員驗證</div>'+\n                '<label class=\"cabinet-auth-label\" for=\"cabinet-admin-password\">管理密碼</label>'+\n                '<input class=\"cabinet-auth-input\" id=\"cabinet-admin-password\" type=\"password\" autocomplete=\"off\" placeholder=\"輸入管理密碼\">'+\n                '<div class=\"cabinet-auth-help\">輸入管理密碼即可編輯，修改後直接儲存至雲端。</div>'+\n                '<div class=\"cabinet-auth-error\" id=\"cabinet-auth-error\"></div>'+\n                '<div class=\"cabinet-auth-actions\">'+\n                    '<button type=\"button\" id=\"cabinet-auth-cancel\">取消</button>'+\n                    '<button type=\"button\" id=\"cabinet-auth-submit\">驗證並編輯</button>'+\n                '</div>'+\n            '</div>';\n\n        document.body.appendChild(modal);\n\n        const passwordInput=modal.querySelector('#cabinet-admin-password');\n        const error=modal.querySelector('#cabinet-auth-error');\n\n        function dismiss(){\n            modal.hidden=true;\n            passwordInput.value='';\n            error.textContent='';\n        }\n\n        modal.querySelector('#cabinet-auth-cancel').addEventListener('click',dismiss);\n\n        modal.querySelector('#cabinet-auth-submit').addEventListener('click',async function(){\n            const password=passwordInput.value;\n            if(!password){\n                error.textContent='請輸入管理密碼。';\n                return;\n            }\n\n            const button=modal.querySelector('#cabinet-auth-submit');\n            button.disabled=true;\n            error.textContent='正在驗證……';\n\n            try{\n                await verifyCabinetPassword(password);\n                cabinetPassword=password;\n                dismiss();\n                enableEditing();\n            }catch(e){\n                error.textContent=e.message||'管理員驗證失敗。';\n            }finally{\n                button.disabled=false;\n            }\n        });\n\n        modal.addEventListener('keydown',function(e){\n            if(e.key==='Escape') dismiss();\n            if(e.key==='Enter' && e.target.tagName==='INPUT'){\n                modal.querySelector('#cabinet-auth-submit').click();\n            }\n        });\n\n        return modal;\n    }\n\n    async function verifyCabinetPassword(password){\n        const response=await fetchCabinetApi({\n            method:'POST',\n            headers:{'Content-Type':'application/json'},\n            body:JSON.stringify({action:'verify',password:password}),\n            cache:'no-store'\n        });\n        const result=await response.json().catch(function(){return {};});\n        if(response.status===403) throw new Error('管理密碼錯誤。');\n        if(!response.ok) throw new Error(result.error||('驗證服務暫時無法使用（HTTP '+response.status+'）。'));\n        return true;\n    }\n\n    async function saveToCloud(){\n        if(!editing || !cabinetPassword) return;\n\n        const saveButton=document.getElementById('cabinet-save-button');\n        if(saveButton) saveButton.disabled=true;\n        setStatus('正在儲存','loading');\n\n        try{\n            const response=await fetchCabinetApi({\n                method:'PUT',\n                headers:{\n                    'Content-Type':'application/json',\n                    'X-WME-Edit-Password':cabinetPassword\n                },\n                body:JSON.stringify({savedData:getSnapshot()}),\n                cache:'no-store'\n            });\n            const result=await response.json().catch(function(){return {};});\n            if(!response.ok) throw new Error(result.error||('雲端儲存失敗（HTTP '+response.status+'）。'));\n\n            closeEditing();\n            setStatus('在線中','online');\n        }catch(e){\n            setStatus('離線中','error');\n            alert(e.message||'雲端儲存失敗，修改尚未提交。');\n        }finally{\n            if(saveButton) saveButton.disabled=false;\n        }\n    }\n\n    function bindToolbar(){\n        const saveButton=document.getElementById('cabinet-save-button');\n        const cancelButton=document.getElementById('cabinet-cancel-button');\n        if(saveButton) saveButton.addEventListener('click',saveToCloud);\n        if(cancelButton) cancelButton.addEventListener('click',cancelEditing);\n    }\n\n    function cancelEditing(){\n        if(!editing) return;\n        if(!confirm('放棄本次尚未提交的修改？')) return;\n        setBackup();\n        closeEditing();\n        setStatus('在線中','online');\n    }\n\n\n    tb.addEventListener('click',function(e){\n        if(!editing) return;\n        const box=e.target.closest('.wm-portrait-box');\n        if(!box) return;\n\n        const url=prompt('輸入新肖像網址：');\n        if(!url) return;\n\n        try{\n            const parsed=new URL(url.trim());\n            if(parsed.protocol!=='https:' && parsed.protocol!=='http:'){\n                alert('請輸入有效的圖片網址。');\n                return;\n            }\n            const img=document.createElement('img');\n            img.src=parsed.href;\n            img.className='wm-portrait-img';\n            img.alt='官員肖像';\n            box.replaceChildren(img);\n            markDirty();\n        }catch(e){\n            alert('圖片網址格式不正確。');\n        }\n    });\n\n    async function loadData(){\n        setStatus('讀取中','loading');\n        let timeout=null;\n        try{\n            const controller=new AbortController();\n            timeout=setTimeout(function(){controller.abort();},12000);\n            let response=await fetch(CABINET_API,{\n                cache:'no-store',\n                signal:controller.signal\n            });\n            const apiContentType=response.headers.get('content-type')||'';\n            if(response.status===404 && !apiContentType.includes('application/json')){\n                response=await fetch('./cabinet.json',{\n                    cache:'no-cache',\n                    signal:controller.signal\n                });\n            }\n            if(!response.ok) throw new Error('內閣資料讀取失敗（HTTP '+response.status+'）。');\n            const data=await response.json();\n            if(data.savedData){\n                if(typeof data.savedData.header==='string') header.innerHTML=data.savedData.header;\n                if(typeof data.savedData.table==='string') tb.innerHTML=data.savedData.table;\n                if(typeof data.savedData.footer==='string') footer.innerHTML=data.savedData.footer;\n            }else if(typeof data.savedHTML==='string'){\n                tb.innerHTML=data.savedHTML;\n            }else{\n                throw new Error('cabinet.json 缺少 savedHTML。');\n            }\n            lockDownEditing();\n            cleanEmptyNames();\n            status.title='';\n            setStatus('在線中','online');\n        }catch(e){\n            console.error('內閣資料讀取失敗：',e);\n            tb.innerHTML=INITIAL_HTML;\n            lockDownEditing();\n            cleanEmptyNames();\n            status.title=e && e.message ? e.message : '未知讀取錯誤';\n            setStatus('離線中','error');\n        }finally{\n            if(timeout!==null) clearTimeout(timeout);\n            scheduleEmbedHeight();\n        }\n    }\n\n    const editTrigger=document.getElementById('cabinet-edit-trigger');\n    editTrigger.addEventListener('click',function(){\n        if(editing) return;\n        const modal=createAuthModal();\n        modal.hidden=false;\n        const passwordInput=modal.querySelector('#cabinet-admin-password');\n        setTimeout(function(){passwordInput.focus();},0);\n    });\n\n    bindToolbar();\n    loadData().then(scheduleEmbedHeight);\n\n    // iframe 嵌入支援：只回報內容本身高度，不把 iframe 視窗高度算進去。\n    function notifyEmbedHeight(){\n        if(window.parent===window) return;\n        const rect=app.getBoundingClientRect();\n        const style=window.getComputedStyle(app);\n        const marginBottom=parseFloat(style.marginBottom)||0;\n        const height=Math.ceil(rect.bottom+window.scrollY+marginBottom);\n        window.parent.postMessage({\n            type:'wme-cabinet-embed-height',\n            height:Math.max(height,1)\n        },'*');\n    }\n\n    let embedHeightFrame=0;\n    function scheduleEmbedHeight(){\n        if(window.parent===window) return;\n        cancelAnimationFrame(embedHeightFrame);\n        embedHeightFrame=requestAnimationFrame(function(){\n            requestAnimationFrame(notifyEmbedHeight);\n        });\n    }\n\n    if(window.parent!==window){\n        window.addEventListener('load',scheduleEmbedHeight);\n        window.addEventListener('resize',scheduleEmbedHeight);\n\n        if('ResizeObserver' in window){\n            const embedResizeObserver=new ResizeObserver(scheduleEmbedHeight);\n            embedResizeObserver.observe(document.documentElement);\n            embedResizeObserver.observe(app);\n        }\n\n        const embedMutationObserver=new MutationObserver(scheduleEmbedHeight);\n        embedMutationObserver.observe(app,{\n            childList:true,\n            subtree:true,\n            characterData:true,\n            attributes:true\n        });\n\n        if(document.fonts && document.fonts.ready){\n            document.fonts.ready.then(scheduleEmbedHeight);\n        }\n        scheduleEmbedHeight();\n    }\n\n\n})();\n</script>\n</body>\n</html>\n","/":"<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta http-equiv=\"refresh\" content=\"0; url=./privy.html\">\n<title>黃名帝國官職表</title>\n<link rel=\"canonical\" href=\"./privy.html\">\n</head>\n<body>\n<p>正在開啟司憲院制司受憲秘閣院職官表……</p>\n<script>location.replace('./privy.html');</script>\n</body>\n</html>\n"};
const JSON_HEADERS = {"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"};
function reply(data,status=200){return new Response(JSON.stringify(data),{status,headers:JSON_HEADERS});}
function same(a,b){
 if(typeof a!=="string"||typeof b!=="string"||a.length!==b.length)return false;
 let d=0;for(let i=0;i<a.length;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);return d===0;
}
async function api(request,env,key){
 if(!env.DB)return reply({error:"D1 資料庫尚未綁定。"},503);
 if(request.method==="GET"){
  try{
   const row=await env.DB.prepare("SELECT payload FROM wme_documents WHERE document_key=?1").bind(key).first();
   if(!row)return reply({error:"找不到名冊資料。"},404);
   return new Response(row.payload,{headers:JSON_HEADERS});
  }catch(e){return reply({error:e.message||"讀取資料失敗。"},500);}
 }
 if(request.method!=="POST"&&request.method!=="PUT")return reply({error:"Method Not Allowed"},405);
 const expected=env.WME_EDIT_PASSWORD||"";
 if(!expected)return reply({error:"管理密碼尚未設定。"},503);
 if(request.method==="POST"){
  let body;try{body=await request.json();}catch{return reply({error:"JSON 格式錯誤。"},400);}
  if(body.action!=="verify")return reply({error:"未知操作。"},400);
  if(!same(body.password,expected))return reply({error:"管理密碼錯誤。"},403);
  return reply({ok:true});
 }
 if(!same(request.headers.get("X-WME-Edit-Password"),expected))return reply({error:"管理密碼錯誤，未儲存。"},403);
 let body;try{
  const raw=await request.text();if(raw.length>1048576)return reply({error:"資料超過 1 MB 限制。"},413);
  body=JSON.parse(raw);
 }catch{return reply({error:"JSON 格式錯誤。"},400);}
 const saved=body.savedData;
 if(!saved||!["header","table","footer"].every(k=>typeof saved[k]==="string"))return reply({error:"儲存資料必須包含 header、table、footer。"},400);
 try{
  const row=await env.DB.prepare("SELECT payload FROM wme_documents WHERE document_key=?1").bind(key).first();
  if(!row)return reply({error:"資料庫尚未匯入原始名冊，已停止儲存以免覆蓋。"},404);
  const doc=JSON.parse(row.payload),now=new Date().toISOString();
  doc.version=doc.version||1;doc.updatedAt=now;doc.savedHTML=saved.table;
  doc.savedData={header:saved.header,table:saved.table,footer:saved.footer};
  await env.DB.prepare("UPDATE wme_documents SET payload=?1,updated_at=?2 WHERE document_key=?3")
   .bind(JSON.stringify(doc),now,key).run();
  return reply({ok:true,updatedAt:now});
 }catch(e){return reply({error:e.message||"資料庫儲存失敗。"},500);}
}
export default {
 async fetch(request,env){
  const url=new URL(request.url),path=url.pathname;
  if(path==="/api/health"){
   try{
    if(!env.DB)throw new Error("D1 binding missing");
    const rows=await env.DB.prepare("SELECT document_key FROM wme_documents ORDER BY document_key").all();
    return reply({ok:true,d1Configured:true,passwordConfigured:!!env.WME_EDIT_PASSWORD,d1Documents:rows.results?.map(x=>x.document_key)||[]});
   }catch(e){return reply({ok:false,d1Configured:!!env.DB,passwordConfigured:!!env.WME_EDIT_PASSWORD,error:e.message||"D1 health check failed"},503);}
  }
  const match=path.match(/^\/api\/(privy|cabinet)$/);
  if(match)return api(request,env,match[1]);
  if(path==="/"||PAGES[path]){
   const page=PAGES[path]||PAGES["/"];
   return new Response(page,{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
  }
  return new Response("Not Found",{status:404});
 }
};
